function fpsSfx(name, vol) {
  try {
    if (!F.audio[name]) {
      F.audio[name] = new Audio('./sfx/' + name + '.mp3');
      F.audio[name].preload = 'auto';
    }
    var a = F.audio[name].cloneNode();
    a.volume = vol == null ? 0.55 : vol;
    var p = a.play();
    if (p && p.catch) p.catch(function(){});
  } catch (e) {}
}

