  try { runtimeScene.getGame().getSceneStack().replace('Maze'); } catch (e) {
    try { window.location.reload(); } catch (e2) {}
  }
}

fpsStartMusic();
fpsEnsureHud();

var player = fpsPlayerPos();
if (!player) { fpsUpdateHud(); }
